/**

 * src/App.js

 * Root component: handles auth state, socket lifecycle,

 * routes between HomeScreen and main chat UI.

 */

import React, { useEffect, useState, useCallback } from 'react';

import { StoreProvider, useStore, A } from './store/userStore';

import HomeScreen      from './components/HomeScreen';

import ChatsList       from './components/ChatsList';

import ChatWindow      from './components/ChatWindow';

import InboxModal      from './components/InboxModal';

import InventoryModal  from './components/InventoryModal';

import LeaderboardModal from './components/LeaderboardModal';

import { COLORS, RADIUS, SHADOW } from './styles/theme';

import { connectSocket, disconnectSocket, joinChat } from './socket/socket';

// BUG FIX: getToken was previously require()'d inside initSocket callback.

// require() is not valid in ES modules — moved to a top-level import.

import { validateToken, logout, getToken } from './api/auth';

import { fetchChats } from './api/restHelpers';

import { formatCoins, initials, userColor } from './utils/formatters';

// ─── Toast rack ───────────────────────────────────────────────────────────────

function ToastRack() {

  const { state, dispatch } = useStore();

  return (

    <div style={{

      position:   'fixed',

      top:        '16px',

      right:      '16px',

      zIndex:     999,

      display:    'flex',

      flexDirection:'column',

      gap:        '8px',

      pointerEvents:'none',

    }}>

      {state.toasts.map(t => (

        <div key={t.id} style={{

          padding:      '10px 16px',

          background:   COLORS.bg3,

          border:       `1px solid ${

            t.type === 'error'   ? COLORS.danger  :

            t.type === 'success' ? COLORS.mint    :

            t.type === 'warning' ? COLORS.warning : COLORS.border

          }`,

          borderRadius: RADIUS.md,

          boxShadow:    SHADOW.card,

          fontFamily:   'var(--font-mono)',

          fontSize:     '12px',

          color:        t.type === 'error' ? COLORS.danger : COLORS.textPrimary,

          maxWidth:     '300px',

          animation:    'toastIn 0.2s ease',

        }}>

          {t.text}

        </div>

      ))}

    </div>

  );

}

// ─── User avatar pill (top-right) ─────────────────────────────────────────────

function UserPill({ user, onLogout, onLeaderboard, onInbox, inboxUnread }) {

  const color = userColor(user.id);

  return (

    <div style={{

      display:    'flex',

      alignItems: 'center',

      gap:        '8px',

      padding:    '8px 14px',

      borderBottom:`1px solid ${COLORS.border}`,

      background: COLORS.bg1,

    }}>

      <div style={{

        width:          28, height: 28,

        borderRadius:   RADIUS.sm,

        background:     `${color}22`,

        border:         `1px solid ${color}44`,

        display:        'flex', alignItems:'center', justifyContent:'center',

        fontSize:       '11px', fontFamily:'var(--font-mono)', fontWeight:'600',

        color, flexShrink: 0,

      }}>

        {initials(user.username)}

      </div>

      <div style={{ flex:1, minWidth:0 }}>

        <div style={{

          fontSize:'12px', fontFamily:'var(--font-display)', fontWeight:'600',

          color:COLORS.textPrimary, whiteSpace:'nowrap', overflow:'hidden', textOverflow:'ellipsis',

        }}>

          {user.username}

        </div>

        {user.wallet != null && (

          <div style={{ fontSize:'10px', fontFamily:'var(--font-mono)', color:COLORS.mint }}>

            💰 {formatCoins(user.wallet)}

          </div>

        )}

      </div>

      {/* Fix #6: Inbox button with unread badge */}

      <button

        onClick={onInbox}

        title="Inbox"

        style={{

          position:    'relative',

          background:  'transparent',

          border:      `1px solid ${inboxUnread > 0 ? COLORS.blue + '66' : COLORS.border}`,

          borderRadius: RADIUS.sm,

          color:       inboxUnread > 0 ? COLORS.blue : COLORS.textSecondary,

          fontSize:    '14px',

          padding:     '3px 7px',

          cursor:      'pointer',

        }}

      >

        📬

        {inboxUnread > 0 && (

          <span style={{

            position:       'absolute',

            top:            '-5px',

            right:          '-5px',

            minWidth:       '16px',

            height:         '16px',

            borderRadius:   RADIUS.pill,

            background:     COLORS.blue,

            color:          COLORS.bg0,

            fontSize:       '9px',

            fontFamily:     'var(--font-mono)',

            fontWeight:     '700',

            display:        'flex',

            alignItems:     'center',

            justifyContent: 'center',

            padding:        '0 4px',

          }}>

            {inboxUnread > 9 ? '9+' : inboxUnread}

          </span>

        )}

      </button>

      <button

        onClick={onLeaderboard}

        title="Leaderboard"

        style={{

          background:'transparent', border:`1px solid ${COLORS.border}`,

          borderRadius:RADIUS.sm, color:COLORS.textSecondary,

          fontSize:'14px', padding:'3px 7px', cursor:'pointer',

        }}

      >

        🏆

      </button>

      <button

        onClick={onLogout}

        title="Logout"

        style={{

          background:'transparent', border:`1px solid ${COLORS.border}`,

          borderRadius:RADIUS.sm, color:COLORS.textSecondary,

          fontSize:'14px', padding:'3px 7px', cursor:'pointer',

        }}

      >

        ⏻

      </button>

    </div>

  );

}

// ─── Inner app (needs store) ───────────────────────────────────────────────────

function Inner() {

  const { state, dispatch, toast } = useStore();

  const [showInventory,   setShowInventory]   = useState(false);

  const [showLeaderboard, setShowLeaderboard] = useState(false);

  const [showInbox,       setShowInbox]       = useState(false);

  // ── Auth check on mount ──────────────────────────────────────────────────────

  useEffect(() => {

    validateToken().then(user => {

      if (user) {

        dispatch({ type: A.SET_USER, payload: user });

        initSocket(user);

      }

    });

  }, []); // eslint-disable-line

  // ── Socket setup ─────────────────────────────────────────────────────────────

  const initSocket = useCallback((user) => {

    // BUG FIX: was require('./api/auth') here — not valid in ES modules.

    // getToken is now a top-level import.

    const token = getToken();

    if (!token) return;

    connectSocket(token, {

      onConnect: () => {

        dispatch({ type: A.SET_CONNECTED, payload: true });

        // Join user's chats

        fetchChats().then(chats => {

          dispatch({ type: A.SET_CHATS, payload: chats });

          chats.forEach(c => joinChat(c.id));

          // Default to first chat (Homiesphere)

          if (chats.length && !state.currentChatId) {

            dispatch({ type: A.SET_CURRENT_CHAT, payload: chats[0].id });

          }

        }).catch(() => toast('error', 'Failed to load chats'));

      },

      onDisconnect: () => {

        dispatch({ type: A.SET_CONNECTED, payload: false });

      },

      onMessage: (msg) => {

        dispatch({ type: A.APPEND_MESSAGE, payload: { chatId: msg.chat_id, message: msg } });

        // If it's an inventory-related bot card, check for trigger

        if (msg.metadata?.card?.buttons?.some(b => b.action === 'open_inventory')) {

          // Could auto-open modal, but leave it user-triggered

        }

      },

      onPrivateMessage: (msg) => {

        dispatch({ type: A.APPEND_PRIVATE, payload: msg });

        toast('info', '📬 You have a new private message');

      },

      onInventoryUpdated: (payload) => {

        if (payload.inventory) {

          dispatch({ type: A.SET_INVENTORY, payload: payload.inventory });

        }

      },

      onError: (err) => {

        toast('error', err.message || 'Connection error');

      },

    });

  }, [dispatch, toast]); // eslint-disable-line

  // ── Login handler ─────────────────────────────────────────────────────────────

  function handleLogin(data) {

    dispatch({ type: A.SET_USER, payload: data.user });

    dispatch({ type: A.SET_CHATS, payload: data.chats || [] });

    if (data.chats?.length) {

      dispatch({ type: A.SET_CURRENT_CHAT, payload: data.chats[0].id });

    }

    initSocket(data.user);

  }

  // ── Logout ────────────────────────────────────────────────────────────────────

  async function handleLogout() {

    disconnectSocket();

    await logout();

    dispatch({ type: A.LOGOUT });

  }

  // ── Not logged in ─────────────────────────────────────────────────────────────

  if (!state.user) {

    return <HomeScreen onLogin={handleLogin} />;

  }

  // ── Main app shell ────────────────────────────────────────────────────────────

  return (

    <div style={{

      height:       '100vh',

      display:      'flex',

      flexDirection:'column',

      background:   COLORS.bg0,

      overflow:     'hidden',

    }}>

      {/* Main layout */}

      <div style={{ flex: 1, display: 'flex', overflow: 'hidden' }}>

        {/* Sidebar */}

        <div style={{ display: 'flex', flexDirection: 'column', flexShrink: 0, width: '230px' }}>

          <UserPill

            user={state.user}

            onLogout={handleLogout}

            onLeaderboard={() => setShowLeaderboard(true)}

            onInbox={() => setShowInbox(true)}

            inboxUnread={state.inboxUnread || 0}

          />

          <ChatsList />

        </div>

        {/* Chat area */}

        <div style={{ flex: 1, display: 'flex', overflow: 'hidden', position: 'relative' }}>

          <ChatWindow />

          {/* Floating inventory button */}

          <button

            onClick={() => setShowInventory(true)}

            title="Inventory"

            style={{

              position:     'absolute',

              bottom:       '90px',

              right:        '16px',

              width:        '42px',

              height:       '42px',

              borderRadius: RADIUS.md,

              background:   COLORS.bg3,

              border:       `1px solid ${COLORS.borderMint}`,

              color:        COLORS.mint,

              fontSize:     '18px',

              cursor:       'pointer',

              display:      'flex',

              alignItems:   'center',

              justifyContent:'center',

              boxShadow:    SHADOW.mint,

              zIndex:       10,

              transition:   'all 0.15s',

            }}

            onMouseEnter={e => {

              e.currentTarget.style.background = COLORS.mintGlow;

              e.currentTarget.style.transform  = 'scale(1.05)';

            }}

            onMouseLeave={e => {

              e.currentTarget.style.background = COLORS.bg3;

              e.currentTarget.style.transform  = 'scale(1)';

            }}

          >

            🎒

          </button>

        </div>

      </div>

      {/* Modals */}

      {showInventory && (

        <InventoryModal

          chatId={state.currentChatId}

          onClose={() => setShowInventory(false)}

        />

      )}

      {showLeaderboard && (

        <LeaderboardModal onClose={() => setShowLeaderboard(false)} />

      )}

      {/* Fix #6: Inbox modal for private messages */}

      {showInbox && (

        <InboxModal onClose={() => setShowInbox(false)} />

      )}

      {/* Toasts */}

      <ToastRack />

    </div>

  );

}

// ─── Root wrapper ─────────────────────────────────────────────────────────────

export default function App() {

  return (

    <StoreProvider>

      <Inner />

    </StoreProvider>

  );

}

