/**
 * components/MessageBubble.js
 * Renders a single message: user text bubble, bot text+card, or system notice.
 */

import React from 'react';
import BotCard from './BotCard';
import { COLORS, RADIUS } from '../styles/theme';
import { formatTime, initials, userColor } from '../utils/formatters';
import { useStore } from '../store/userStore';

// ─── Bot avatar ───────────────────────────────────────────────────────────────
function BotAvatar() {
  return (
    <div style={{
      width:          32,
      height:         32,
      borderRadius:   RADIUS.sm,
      background:     `${COLORS.mint}22`,
      border:         `1px solid ${COLORS.borderMint}`,
      display:        'flex',
      alignItems:     'center',
      justifyContent: 'center',
      fontSize:       '14px',
      flexShrink:     0,
    }}>
      🤖
    </div>
  );
}

// ─── User avatar ──────────────────────────────────────────────────────────────
function UserAvatar({ username, userId }) {
  const color = userColor(userId);
  return (
    <div style={{
      width:          32,
      height:         32,
      borderRadius:   RADIUS.sm,
      background:     `${color}22`,
      border:         `1px solid ${color}44`,
      display:        'flex',
      alignItems:     'center',
      justifyContent: 'center',
      fontSize:       '11px',
      fontFamily:     'var(--font-mono)',
      fontWeight:     '600',
      color,
      flexShrink:     0,
    }}>
      {initials(username)}
    </div>
  );
}

// ─── System message ────────────────────────────────────────────────────────────
function SystemMessage({ content, timestamp }) {
  return (
    <div style={{
      display:        'flex',
      justifyContent: 'center',
      padding:        '4px 0',
    }}>
      <span style={{
        fontSize:     '11px',
        fontFamily:   'var(--font-mono)',
        color:        COLORS.textMuted,
        background:   COLORS.bg3,
        border:       `1px solid ${COLORS.border}`,
        borderRadius: RADIUS.pill,
        padding:      '3px 12px',
        letterSpacing:'0.03em',
      }}>
        {content}
      </span>
    </div>
  );
}

// ─── Main component ────────────────────────────────────────────────────────────
export default function MessageBubble({ message, chatId }) {
  const { state } = useStore();
  const isMine  = message.sender_id === state.user?.id;
  const isBot   = message.type === 'bot';
  const isSys   = message.type === 'system';
  const card    = message.metadata?.card;
  const personality = message.metadata?.personality;

  if (isSys) {
    return <SystemMessage content={message.content} timestamp={message.timestamp} />;
  }

  return (
    <div style={{
      display:        'flex',
      flexDirection:  isMine ? 'row-reverse' : 'row',
      alignItems:     'flex-start',
      gap:            '8px',
      padding:        '4px 0',
      opacity:        1,
      animation:      'fadeSlideIn 0.18s ease',
    }}>
      {/* Avatar */}
      {isBot
        ? <BotAvatar />
        : !isMine && (
            <UserAvatar
              username={message.username || message.sender_id}
              userId={message.sender_id}
            />
          )
      }

      {/* Content */}
      <div style={{
        display:  'flex',
        flexDirection: 'column',
        gap:      '6px',
        maxWidth: '80%',
        alignItems: isMine ? 'flex-end' : 'flex-start',
      }}>
        {/* Sender name + time */}
        {!isMine && (
          <div style={{
            display:    'flex',
            alignItems: 'center',
            gap:        '8px',
          }}>
            <span style={{
              fontSize:   '11px',
              fontFamily: 'var(--font-mono)',
              fontWeight: '500',
              color:      isBot ? COLORS.mint : userColor(message.sender_id),
            }}>
              {isBot ? 'GameBot' : (message.username || message.sender_id)}
            </span>
            <span style={{
              fontSize:  '10px',
              fontFamily:'var(--font-mono)',
              color:     COLORS.textMuted,
            }}>
              {formatTime(message.timestamp)}
            </span>
          </div>
        )}

        {/* Text bubble */}
        {message.content && (
          <div style={{
            padding:      '8px 12px',
            borderRadius: isMine
              ? `${RADIUS.lg} ${RADIUS.sm} ${RADIUS.sm} ${RADIUS.lg}`
              : isBot
              ? `${RADIUS.sm} ${RADIUS.lg} ${RADIUS.lg} ${RADIUS.sm}`
              : RADIUS.lg,
            background:   isMine
              ? `${COLORS.mint}18`
              : isBot
              ? `${COLORS.bg3}`
              : COLORS.bg3,
            border: isMine
              ? `1px solid ${COLORS.borderMint}`
              : `1px solid ${COLORS.border}`,
            fontSize:     '13px',
            fontFamily:   'var(--font-body)',
            lineHeight:   '1.5',
            color:        isBot ? COLORS.textBot : COLORS.textPrimary,
            maxWidth:     '100%',
            wordBreak:    'break-word',
          }}>
            {message.content}
          </div>
        )}

        {/* Bot card */}
        {isBot && card && (
          <BotCard
            card={card}
            personality={personality}
            chatId={chatId}
            messageId={message.id}
          />
        )}

        {/* Timestamp for own messages */}
        {isMine && (
          <span style={{
            fontSize:  '10px',
            fontFamily:'var(--font-mono)',
            color:     COLORS.textMuted,
          }}>
            {formatTime(message.timestamp)}
          </span>
        )}
      </div>
    </div>
  );
}
