/**
 * api/auth.js
 * HTTP auth layer — login, token persistence, logout.
 * All REST calls go through here so the base URL is one change.
 */

const BASE = (() => {
  const url = process.env.REACT_APP_SERVER_URL;
  if (!url && process.env.NODE_ENV === 'production') {
    throw new Error('[auth.js] REACT_APP_SERVER_URL is not set.');
  }
  return url || 'http://localhost:3001';
})();
const TOKEN_KEY = 'gb_token';
const USER_KEY  = 'gb_user';

// ─── Token helpers ────────────────────────────────────────────────────────────

export function saveToken(token) {
  localStorage.setItem(TOKEN_KEY, token);
}

export function getToken() {
  return localStorage.getItem(TOKEN_KEY);
}

export function clearToken() {
  localStorage.removeItem(TOKEN_KEY);
  localStorage.removeItem(USER_KEY);
}

export function saveUser(user) {
  localStorage.setItem(USER_KEY, JSON.stringify(user));
}

export function getSavedUser() {
  try {
    const raw = localStorage.getItem(USER_KEY);
    return raw ? JSON.parse(raw) : null;
  } catch {
    return null;
  }
}

// ─── API calls ────────────────────────────────────────────────────────────────

/**
 * Log in with username + password.
 * Server should return { token, user, chats }.
 *
 * @param {string} username
 * @param {string} password
 * @returns {Promise<{ token: string, user: object, chats: object[] }>}
 */
export async function login(username, password) {
  const res = await fetch(`${BASE}/api/auth/login`, {
    method:  'POST',
    headers: { 'Content-Type': 'application/json' },
    body:    JSON.stringify({ username, password }),
  });

  if (!res.ok) {
    const err = await res.json().catch(() => ({}));
    throw new Error(err.message || `Login failed (${res.status})`);
  }

  const data = await res.json();
  saveToken(data.token);
  saveUser(data.user);
  return data;   // { token, user, chats }
}

/**
 * Register a new account.
 * Server should return { token, user, chats }.
 *
 * @param {string} username
 * @param {string} password
 * @returns {Promise<{ token: string, user: object, chats: object[] }>}
 */
export async function register(username, password) {
  const res = await fetch(`${BASE}/api/auth/register`, {
    method:  'POST',
    headers: { 'Content-Type': 'application/json' },
    body:    JSON.stringify({ username, password }),
  });

  if (!res.ok) {
    const err = await res.json().catch(() => ({}));
    throw new Error(err.message || `Registration failed (${res.status})`);
  }

  const data = await res.json();
  saveToken(data.token);
  saveUser(data.user);
  return data;   // { token, user, chats }
}

/**
 * Logout — clears local storage.
 * Call before socket.disconnect() so token is invalid server-side too.
 */
export async function logout() {
  const token = getToken();
  if (token) {
    // Best-effort server logout — fire and forget
    fetch(`${BASE}/api/auth/logout`, {
      method:  'POST',
      headers: { Authorization: `Bearer ${token}` },
    }).catch(() => {});
  }
  clearToken();
}

/**
 * Validate stored token with the server.
 * Returns user object if valid, null if expired/invalid.
 *
 * @returns {Promise<object|null>}
 */
export async function validateToken() {
  const token = getToken();
  if (!token) return null;

  try {
    const res = await fetch(`${BASE}/api/auth/me`, {
      headers: { Authorization: `Bearer ${token}` },
    });
    if (!res.ok) {
      clearToken();
      return null;
    }
    const data = await res.json();
    saveUser(data.user);
    return data.user;
  } catch {
    return null;
  }
}
