/**
 * components/ChatWindow.js
 * Full chat view: fetches history via REST on mount, renders messages,
 * auto-scrolls to bottom on new messages.
 */

import React, { useEffect, useRef, useCallback, useState } from 'react';
import MessageBubble from './MessageBubble';
import Composer from './Composer';
import { COLORS, RADIUS } from '../styles/theme';
import { useStore, A, selectCurrentMessages, selectCurrentChat } from '../store/userStore';
import { fetchChatHistory } from '../api/restHelpers';

export default function ChatWindow() {
  const { state, dispatch } = useStore();
  const messages    = selectCurrentMessages(state);
  const currentChat = selectCurrentChat(state);
  const chatId      = state.currentChatId;

  const bottomRef   = useRef(null);
  const [loading, setLoading] = useState(false);
  const [page, setPage]       = useState(1);
  const [hasMore, setHasMore] = useState(true);

  // ── Fetch history on chat open ─────────────────────────────────────────────
  useEffect(() => {
    if (!chatId) return;
    setPage(1);
    setHasMore(true);

    setLoading(true);
    fetchChatHistory(chatId, 1)
      .then(data => {
        dispatch({ type: A.SET_HISTORY, payload: { chatId, messages: data.messages || [] } });
        if ((data.messages?.length || 0) < 30) setHasMore(false);
      })
      .catch(err => console.error('[ChatWindow] history fetch failed:', err))
      .finally(() => setLoading(false));
  }, [chatId, dispatch]);

  // ── Auto-scroll to bottom on new messages ─────────────────────────────────
  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages.length]);

  // ── Load more (scroll to top) ──────────────────────────────────────────────
  const loadMore = useCallback(async () => {
    if (!hasMore || loading || !chatId) return;
    const nextPage = page + 1;
    setLoading(true);
    try {
      const data = await fetchChatHistory(chatId, nextPage);
      const older = data.messages || [];
      const current = state.messages[chatId] || [];
      dispatch({
        type: A.SET_HISTORY,
        payload: { chatId, messages: [...older, ...current] },
      });
      setPage(nextPage);
      if (older.length < 30) setHasMore(false);
    } catch (err) {
      console.error('[ChatWindow] loadMore failed:', err);
    } finally {
      setLoading(false);
    }
  }, [chatId, hasMore, loading, page, state.messages, dispatch]);

  // ─── Empty state ────────────────────────────────────────────────────────────
  if (!chatId) {
    return (
      <div style={{
        flex:           1,
        display:        'flex',
        alignItems:     'center',
        justifyContent: 'center',
        background:     COLORS.bg2,
        flexDirection:  'column',
        gap:            '12px',
      }}>
        <div style={{ fontSize: '40px' }}>🔱</div>
        <span style={{
          fontFamily: 'var(--font-display)',
          fontSize:   '16px',
          color:      COLORS.textMuted,
          letterSpacing: '0.05em',
        }}>
          Select a chat to get started
        </span>
      </div>
    );
  }

  return (
    <div style={{
      flex:        1,
      display:     'flex',
      flexDirection:'column',
      background:  COLORS.bg2,
      overflow:    'hidden',
    }}>
      {/* Chat header */}
      <div style={{
        padding:      '12px 20px',
        borderBottom: `1px solid ${COLORS.border}`,
        display:      'flex',
        alignItems:   'center',
        gap:          '10px',
        background:   COLORS.bg1,
        flexShrink:   0,
      }}>
        <div style={{
          width:          10,
          height:         10,
          borderRadius:   '50%',
          background:     state.connected ? COLORS.mint : COLORS.textMuted,
          boxShadow:      state.connected ? `0 0 6px ${COLORS.mint}` : 'none',
          flexShrink:     0,
        }} />
        <span style={{
          fontFamily:   'var(--font-display)',
          fontWeight:   '700',
          fontSize:     '15px',
          color:        COLORS.textPrimary,
          letterSpacing:'0.01em',
        }}>
          {currentChat?.name || chatId}
        </span>
        {currentChat?.type === 'global' && (
          <span style={{
            fontSize:     '10px',
            fontFamily:   'var(--font-mono)',
            color:        COLORS.mint,
            background:   COLORS.mintGlow,
            border:       `1px solid ${COLORS.borderMint}`,
            borderRadius: RADIUS.pill,
            padding:      '2px 8px',
            letterSpacing:'0.06em',
            textTransform:'uppercase',
          }}>
            Homiesphere
          </span>
        )}
      </div>

      {/* Messages area */}
      <div
        style={{
          flex:       1,
          overflowY:  'auto',
          padding:    '16px 20px',
          display:    'flex',
          flexDirection:'column',
          gap:        '4px',
          scrollbarWidth: 'thin',
          scrollbarColor: `${COLORS.bg4} transparent`,
        }}
      >
        {/* Load more button */}
        {hasMore && (
          <div style={{ display: 'flex', justifyContent: 'center', marginBottom: '8px' }}>
            <button
              onClick={loadMore}
              disabled={loading}
              style={{
                padding:      '5px 16px',
                fontSize:     '11px',
                fontFamily:   'var(--font-mono)',
                color:        COLORS.textSecondary,
                background:   COLORS.bg3,
                border:       `1px solid ${COLORS.border}`,
                borderRadius: RADIUS.pill,
                cursor:       loading ? 'default' : 'pointer',
              }}
            >
              {loading ? 'Loading…' : '↑ Load earlier messages'}
            </button>
          </div>
        )}

        {loading && messages.length === 0 && (
          <div style={{
            display:        'flex',
            justifyContent: 'center',
            padding:        '40px',
            color:          COLORS.textMuted,
            fontFamily:     'var(--font-mono)',
            fontSize:       '12px',
          }}>
            Loading messages…
          </div>
        )}

        {messages.map(msg => (
          <MessageBubble key={msg.id || msg.timestamp} message={msg} chatId={chatId} />
        ))}

        <div ref={bottomRef} />
      </div>

      {/* Composer */}
      <Composer chatId={chatId} />
    </div>
  );
}
