/**
 * api/restHelpers.js
 * Authenticated REST helpers used to bootstrap initial state
 * before the socket takes over real-time updates.
 */

import { getToken } from './auth';

const BASE = (() => {
  const url = process.env.REACT_APP_SERVER_URL;
  if (!url && process.env.NODE_ENV === 'production') {
    throw new Error('[restHelpers.js] REACT_APP_SERVER_URL is not set.');
  }
  return url || 'http://localhost:3001';
})();

async function authFetch(path, options = {}) {
  const token = getToken();
  const res = await fetch(`${BASE}${path}`, {
    ...options,
    headers: {
      'Content-Type': 'application/json',
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
      ...(options.headers || {}),
    },
  });

  if (!res.ok) {
    const err = await res.json().catch(() => ({}));
    throw new Error(err.message || `Request failed (${res.status})`);
  }

  return res.json();
}

/**
 * Fetch paginated message history for a chat.
 * Called once when a chat is opened; socket handles subsequent messages.
 *
 * @param {string} chatId
 * @param {number} [page=1]
 * @returns {Promise<{ messages: object[], total: number, page: number }>}
 */
export async function fetchChatHistory(chatId, page = 1) {
  return authFetch(`/api/chats/${chatId}/history?page=${page}`);
}

/**
 * Fetch a player's full profile.
 * @param {string} userId
 * @returns {Promise<object>}
 */
export async function fetchProfile(userId) {
  return authFetch(`/api/player/${userId}`);
}

/**
 * Fetch all chats the user belongs to.
 * @returns {Promise<object[]>}
 */
export async function fetchChats() {
  return authFetch('/api/chats');
}

/**
 * Fetch the user's inventory.
 * @param {string} userId
 * @param {number} [page=1]
 * @returns {Promise<{ items: object[], total: number }>}
 */
export async function fetchInventory(userId, page = 1) {
  return authFetch(`/api/player/${userId}/inventory?page=${page}`);
}

/**
 * Fetch leaderboard for the current season.
 * @param {number} [page=1]
 * @returns {Promise<{ entries: object[], season: object, total: number }>}
 */
export async function fetchLeaderboard(page = 1) {
  return authFetch(`/api/leaderboard?page=${page}`);
}
