/**
 * components/Composer.js
 * Message input bar with quick-command shortcut buttons.
 *
 * Fix #7 — Silent Socket Failures:
 *   The send button and all quick-command buttons are disabled when
 *   state.connected is false. A "Connection Lost" banner replaces the
 *   quick-command strip to make the disruption unmissable rather than silent.
 *
 * Fix #8 — Double-Tap Spam:
 *   submit() sets a 500ms local lock (sendLocked) immediately on click.
 *   While locked the button renders as disabled. The lock clears via
 *   setTimeout regardless of whether the server responded — it's purely
 *   a client-side guard against accidental repeat-fires.
 */

import React, { useState, useRef, useCallback } from 'react';
import { COLORS, RADIUS, SHADOW } from '../styles/theme';
import { sendMessage } from '../socket/socket';
import { useStore } from '../store/userStore';

const QUICK_COMMANDS = [
  { label: '/work',    cmd: '/work',          icon: '💼' },
  { label: '/crime',   cmd: '/crime',         icon: '🔫' },
  { label: '/profile', cmd: '/profile',       icon: '👤' },
  { label: '/shop',    cmd: '/shop',          icon: '🛒' },
  { label: '/inv',     cmd: '/inventory',     icon: '🎒' },
  { label: '/gang',    cmd: '/gang',          icon: '🔱' },
  { label: '/lb',      cmd: '/leaderboard',   icon: '🏆' },
  { label: '/lottery', cmd: '/lottery status',icon: '🎰' },
];

// Lock duration in ms — prevents accidental double-fire on any send action
const SEND_LOCK_MS = 500;

export default function Composer({ chatId }) {
  const { state }                     = useStore();
  const [text, setText]               = useState('');
  const [showCmds, setShowCmds]       = useState(false);
  // Fix #8: local debounce lock — set on send, cleared after SEND_LOCK_MS
  const [sendLocked, setSendLocked]   = useState(false);
  const inputRef                      = useRef(null);

  const connected = state.connected;

  // ── Core submit ─────────────────────────────────────────────────────────────
  const submit = useCallback((value) => {
    const trimmed = (value || text).trim();
    // Fix #7: hard-block if socket is down
    if (!trimmed || !state.user || !chatId || !connected) return;
    // Fix #8: hard-block if within the debounce window
    if (sendLocked) return;

    setSendLocked(true);
    sendMessage(chatId, state.user.id, trimmed);
    setText('');
    inputRef.current?.focus();
    setTimeout(() => setSendLocked(false), SEND_LOCK_MS);
  }, [text, state.user, chatId, connected, sendLocked]);

  function handleKeyDown(e) {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      submit();
    }
    if (e.key === 'Escape') setShowCmds(false);
  }

  function handleChange(e) {
    const val = e.target.value;
    setText(val);
    if (val === '/') setShowCmds(true);
    else if (!val.startsWith('/')) setShowCmds(false);
  }

  function pickQuickCmd(cmd) {
    setText('');
    setShowCmds(false);
    submit(cmd);
  }

  // ── Derived state for render ──────────────────────────────────────────────
  // A button is disabled if: not connected OR send is locally locked
  const isDisabled    = !connected || sendLocked;
  const canSend       = !!text.trim() && !isDisabled;

  return (
    <div style={{
      padding:       '12px 16px',
      background:    COLORS.bg1,
      borderTop:     `1px solid ${COLORS.border}`,
      position:      'relative',
    }}>

      {/* Fix #7 — Connection Lost banner (replaces quick commands when down) */}
      {!connected && (
        <div style={{
          display:        'flex',
          alignItems:     'center',
          justifyContent: 'center',
          gap:            '8px',
          padding:        '7px 12px',
          marginBottom:   '8px',
          background:     `${COLORS.warning}12`,
          border:         `1px solid ${COLORS.warning}44`,
          borderRadius:   RADIUS.md,
          fontSize:       '11px',
          fontFamily:     'var(--font-mono)',
          color:          COLORS.warning,
          letterSpacing:  '0.04em',
        }}>
          <span style={{
            width: '7px', height: '7px', borderRadius: '50%',
            background: COLORS.warning,
            animation: 'pulse 1.4s ease-in-out infinite',
            flexShrink: 0,
          }} />
          Connection lost — messages are blocked until reconnected
        </div>
      )}

      {/* Quick command palette */}
      {showCmds && connected && (
        <div style={{
          position:     'absolute',
          bottom:       '68px',
          left:         '16px',
          right:        '16px',
          background:   COLORS.bg3,
          border:       `1px solid ${COLORS.borderMint}`,
          borderRadius: RADIUS.lg,
          boxShadow:    SHADOW.card,
          overflow:     'hidden',
          zIndex:       100,
        }}>
          <div style={{
            padding:       '8px 12px 4px',
            fontSize:      '10px',
            fontFamily:    'var(--font-mono)',
            color:         COLORS.textMuted,
            letterSpacing: '0.08em',
            textTransform: 'uppercase',
          }}>
            Quick Commands
          </div>
          <div style={{
            display:              'grid',
            gridTemplateColumns:  'repeat(4, 1fr)',
            gap:                  '2px',
            padding:              '4px 8px 8px',
          }}>
            {QUICK_COMMANDS.map(qc => (
              <button
                key={qc.cmd}
                onClick={() => pickQuickCmd(qc.cmd)}
                style={{
                  display:    'flex',
                  alignItems: 'center',
                  gap:        '4px',
                  padding:    '6px 8px',
                  background: 'transparent',
                  border:     `1px solid ${COLORS.border}`,
                  borderRadius:RADIUS.sm,
                  color:      COLORS.textSecondary,
                  fontSize:   '11px',
                  fontFamily: 'var(--font-mono)',
                  cursor:     'pointer',
                  transition: 'all 0.1s',
                  whiteSpace: 'nowrap',
                }}
                onMouseEnter={e => {
                  e.currentTarget.style.borderColor = COLORS.borderMint;
                  e.currentTarget.style.color       = COLORS.mint;
                  e.currentTarget.style.background  = COLORS.mintGlow2;
                }}
                onMouseLeave={e => {
                  e.currentTarget.style.borderColor = COLORS.border;
                  e.currentTarget.style.color       = COLORS.textSecondary;
                  e.currentTarget.style.background  = 'transparent';
                }}
              >
                <span>{qc.icon}</span>
                <span>{qc.label}</span>
              </button>
            ))}
          </div>
        </div>
      )}

      {/* Quick-action strip — hidden while disconnected (banner shows instead) */}
      {connected && (
        <div style={{ display:'flex', gap:'6px', marginBottom:'8px', flexWrap:'wrap' }}>
          {QUICK_COMMANDS.slice(0, 4).map(qc => (
            <button
              key={qc.cmd}
              onClick={() => pickQuickCmd(qc.cmd)}
              disabled={isDisabled}
              title={qc.cmd}
              style={{
                padding:      '4px 10px',
                fontSize:     '11px',
                fontFamily:   'var(--font-mono)',
                color:        COLORS.textSecondary,
                background:   COLORS.bg3,
                border:       `1px solid ${COLORS.border}`,
                borderRadius: RADIUS.sm,
                cursor:       isDisabled ? 'default' : 'pointer',
                transition:   'all 0.12s',
                display:      'flex',
                alignItems:   'center',
                gap:          '4px',
              }}
              onMouseEnter={e => {
                if (!isDisabled) {
                  e.currentTarget.style.color       = COLORS.mint;
                  e.currentTarget.style.borderColor = COLORS.borderMint;
                  e.currentTarget.style.background  = COLORS.mintGlow;
                }
              }}
              onMouseLeave={e => {
                e.currentTarget.style.color       = COLORS.textSecondary;
                e.currentTarget.style.borderColor = COLORS.border;
                e.currentTarget.style.background  = COLORS.bg3;
              }}
            >
              {qc.icon} {qc.label}
            </button>
          ))}
          <button
            onClick={() => setShowCmds(s => !s)}
            style={{
              padding:      '4px 10px',
              fontSize:     '11px',
              fontFamily:   'var(--font-mono)',
              color:        showCmds ? COLORS.mint : COLORS.textMuted,
              background:   showCmds ? COLORS.mintGlow : COLORS.bg3,
              border:       `1px solid ${showCmds ? COLORS.borderMint : COLORS.border}`,
              borderRadius: RADIUS.sm,
              cursor:       'pointer',
              transition:   'all 0.12s',
            }}
          >
            ··· more
          </button>
        </div>
      )}

      {/* Input row */}
      <div style={{ display:'flex', gap:'8px', alignItems:'flex-end' }}>
        <div
          style={{
            flex:         1,
            position:     'relative',
            background:   COLORS.bg4,
            border:       `1px solid ${!connected ? COLORS.warning + '44' : COLORS.border}`,
            borderRadius: RADIUS.lg,
            transition:   'border-color 0.15s',
            opacity:      connected ? 1 : 0.6,
          }}
          onFocusCapture={e => {
            if (connected) e.currentTarget.style.borderColor = COLORS.borderMint;
          }}
          onBlurCapture={e => {
            e.currentTarget.style.borderColor = connected ? COLORS.border : COLORS.warning + '44';
          }}
        >
          <textarea
            ref={inputRef}
            value={text}
            onChange={handleChange}
            onKeyDown={handleKeyDown}
            disabled={!connected}
            placeholder={connected ? 'Type a message or /command…' : 'Reconnecting…'}
            rows={1}
            style={{
              width:      '100%',
              padding:    '10px 14px',
              background: 'transparent',
              border:     'none',
              outline:    'none',
              resize:     'none',
              fontFamily: 'var(--font-body)',
              fontSize:   '13px',
              color:      COLORS.textPrimary,
              lineHeight: '1.5',
              boxSizing:  'border-box',
              overflowY:  'hidden',
              cursor:     connected ? 'text' : 'not-allowed',
            }}
          />
        </div>

        {/* Send button — disabled when disconnected OR locally locked */}
        <button
          onClick={() => submit()}
          disabled={!canSend}
          title={!connected ? 'Connection lost' : sendLocked ? 'Sending…' : 'Send'}
          style={{
            width:          '40px',
            height:         '40px',
            borderRadius:   RADIUS.md,
            background:     canSend ? COLORS.mint : COLORS.bg4,
            border:         `1px solid ${canSend ? COLORS.mint : COLORS.border}`,
            color:          canSend ? COLORS.bg0  : COLORS.textMuted,
            fontSize:       sendLocked ? '12px' : '18px',
            cursor:         canSend ? 'pointer' : 'not-allowed',
            display:        'flex',
            alignItems:     'center',
            justifyContent: 'center',
            flexShrink:     0,
            transition:     'all 0.15s',
            boxShadow:      canSend ? SHADOW.mint : 'none',
          }}
        >
          {sendLocked ? '···' : '↑'}
        </button>
      </div>
    </div>
  );
}
