/**
 * utils/formatters.js
 * Pure formatting helpers — no side effects.
 */

/**
 * Format a timestamp as a short relative or clock string.
 * @param {number|string} ts — unix ms or ISO string
 * @returns {string}
 */
export function formatTime(ts) {
  const d    = new Date(ts);
  const now  = Date.now();
  const diff = now - d.getTime();

  if (diff < 60_000)          return 'just now';
  if (diff < 3_600_000)       return `${Math.floor(diff / 60_000)}m ago`;
  if (diff < 86_400_000)      return d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  return d.toLocaleDateString([], { month: 'short', day: 'numeric' });
}

/**
 * Format a number with locale commas.
 * @param {number} n
 * @returns {string}
 */
export function formatCoins(n) {
  if (n == null) return '0';
  return Number(n).toLocaleString();
}

/**
 * Truncate a string to maxLen, appending ellipsis if needed.
 * @param {string} str
 * @param {number} maxLen
 * @returns {string}
 */
export function truncate(str, maxLen = 40) {
  if (!str) return '';
  return str.length > maxLen ? str.slice(0, maxLen - 1) + '…' : str;
}

/**
 * Convert a snake_case string to Title Case.
 * @param {string} str
 * @returns {string}
 */
export function toTitleCase(str = '') {
  return str.replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
}

/**
 * Generate a stable, deterministic color from a user_id string.
 * Used for user avatars.
 * @param {string} userId
 * @returns {string} hex color
 */
export function userColor(userId = '') {
  const PALETTE = ['#00e5a0','#00c8e0','#a29bfe','#fd79a8','#ff9f43','#55efc4','#74b9ff'];
  let hash = 0;
  for (let i = 0; i < userId.length; i++) {
    hash = (hash << 5) - hash + userId.charCodeAt(i);
    hash |= 0;
  }
  return PALETTE[Math.abs(hash) % PALETTE.length];
}

/**
 * Get initials from a username.
 * @param {string} username
 * @returns {string}
 */
export function initials(username = '') {
  const parts = username.trim().split(/\s+/);
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
  return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
}

/**
 * Format a cooldown in seconds as "Xm Ys" or "Xs".
 * @param {number} secs
 * @returns {string}
 */
export function formatCooldown(secs) {
  if (secs >= 3600) return `${Math.floor(secs / 3600)}h ${Math.floor((secs % 3600) / 60)}m`;
  if (secs >= 60)   return `${Math.floor(secs / 60)}m ${secs % 60}s`;
  return `${secs}s`;
}
