/**
 * components/InventoryModal.js
 * Inventory overlay.
 *
 * Fix #5 — Invisible Data Loop:
 *   The old version relied on state.inventory being pre-populated from a
 *   socket event that the server never actually emitted. The fix uses two
 *   strategies in sequence:
 *     1. On mount, call fetchInventory() directly via REST — guaranteed data,
 *        no dependency on socket state.
 *     2. Also listen via useEffect for when state.inventory is updated by the
 *        server's inventory_updated socket event (now emitted server-side) so
 *        the modal refreshes live if open when a /use fires.
 *
 * Fix #8 — Double-Tap Spam:
 *   The Use button now has a 500ms local lock after click. The button
 *   is disabled during the lock window to prevent accidental double-fires.
 */

import React, { useEffect, useState, useCallback } from 'react';
import { COLORS, RADIUS, SHADOW } from '../styles/theme';
import { sendMessage } from '../socket/socket';
import { fetchInventory } from '../api/restHelpers';
import { useStore } from '../store/userStore';

const RARITY_COLORS = {
  legendary: '#f9ca24',
  epic:      '#a29bfe',
  rare:      '#00c8e0',
  uncommon:  '#00e5a0',
  common:    '#7a82a0',
};

// ─── Item card ────────────────────────────────────────────────────────────────

function ItemCard({ item, chatId, onClose }) {
  const { state }        = useStore();
  const rarityColor      = RARITY_COLORS[item.rarity?.toLowerCase()] || RARITY_COLORS.common;
  // Fix #8: 500ms local lock prevents double-tap Use spam
  const [useLocked, setUseLocked] = useState(false);

  function handleUse() {
    if (useLocked || !state.user || !chatId) return;
    setUseLocked(true);
    sendMessage(chatId, state.user.id, `/use ${item.item_id}`);
    onClose();
    // Lock resets even if modal is closed — no stale state on reopen
    setTimeout(() => setUseLocked(false), 500);
  }

  return (
    <div style={{
      background:    COLORS.bg3,
      border:        `1px solid ${COLORS.border}`,
      borderTop:     `2px solid ${rarityColor}`,
      borderRadius:  RADIUS.md,
      padding:       '12px',
      display:       'flex',
      flexDirection: 'column',
      gap:           '6px',
    }}>
      <div style={{ display:'flex', alignItems:'center', justifyContent:'space-between' }}>
        <span style={{
          fontSize:   '13px',
          fontFamily: 'var(--font-display)',
          fontWeight: '600',
          color:      COLORS.textPrimary,
        }}>
          {item.name}
        </span>
        <span style={{
          fontSize:      '10px',
          fontFamily:    'var(--font-mono)',
          color:         rarityColor,
          background:    `${rarityColor}18`,
          border:        `1px solid ${rarityColor}44`,
          borderRadius:  RADIUS.pill,
          padding:       '2px 7px',
          textTransform: 'capitalize',
        }}>
          {item.rarity}
        </span>
      </div>

      <div style={{
        fontSize:   '11px',
        fontFamily: 'var(--font-body)',
        color:      COLORS.textSecondary,
        lineHeight: '1.4',
      }}>
        {item.description}
      </div>

      <div style={{ display:'flex', alignItems:'center', justifyContent:'space-between', marginTop:'4px' }}>
        <span style={{ fontSize:'12px', fontFamily:'var(--font-mono)', color: COLORS.mint }}>
          ×{item.qty}
        </span>
        <button
          onClick={handleUse}
          disabled={useLocked}
          style={{
            padding:      '4px 12px',
            fontSize:     '11px',
            fontFamily:   'var(--font-mono)',
            color:        useLocked ? COLORS.textMuted : COLORS.mint,
            background:   useLocked ? COLORS.bg4 : COLORS.mintGlow,
            border:       `1px solid ${useLocked ? COLORS.border : COLORS.borderMint}`,
            borderRadius: RADIUS.sm,
            cursor:       useLocked ? 'default' : 'pointer',
            transition:   'all 0.12s',
          }}
          onMouseEnter={e => {
            if (!useLocked) {
              e.currentTarget.style.background = `${COLORS.mint}28`;
              e.currentTarget.style.boxShadow  = SHADOW.mint;
            }
          }}
          onMouseLeave={e => {
            e.currentTarget.style.background = useLocked ? COLORS.bg4 : COLORS.mintGlow;
            e.currentTarget.style.boxShadow  = 'none';
          }}
        >
          {useLocked ? '···' : 'Use'}
        </button>
      </div>
    </div>
  );
}

// ─── Main modal ───────────────────────────────────────────────────────────────

export default function InventoryModal({ chatId, onClose }) {
  const { state }             = useStore();
  const [items, setItems]     = useState([]);
  const [total, setTotal]     = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError]     = useState(null);

  // Fix #5 primary: fetch via REST on mount — reliable, no socket dependency
  const loadInventory = useCallback(async () => {
    if (!state.user) return;
    setLoading(true);
    setError(null);
    try {
      const data = await fetchInventory(state.user.id, 1);
      setItems(data.items || []);
      setTotal(data.total || 0);
    } catch (err) {
      setError('Failed to load inventory. Try again.');
      console.error('[InventoryModal] REST fetch failed:', err);
    } finally {
      setLoading(false);
    }
  }, [state.user]);

  useEffect(() => { loadInventory(); }, [loadInventory]);

  // Fix #5 secondary: if socket emits inventory_updated while modal is open,
  // refresh display from the store without needing another REST call
  useEffect(() => {
    if (state.inventory?.length && !loading) {
      setItems(state.inventory);
      setTotal(state.inventory.length);
    }
  }, [state.inventory]); // eslint-disable-line

  return (
    <div
      style={{
        position:       'fixed',
        inset:          0,
        background:     'rgba(7,8,13,0.85)',
        display:        'flex',
        alignItems:     'center',
        justifyContent: 'center',
        zIndex:         200,
        backdropFilter: 'blur(4px)',
      }}
      onClick={e => { if (e.target === e.currentTarget) onClose(); }}
    >
      <div style={{
        width:         '520px',
        maxHeight:     '75vh',
        background:    COLORS.bg2,
        border:        `1px solid ${COLORS.borderMint}`,
        borderRadius:  RADIUS.xl,
        boxShadow:     `${SHADOW.card}, ${SHADOW.mint}`,
        display:       'flex',
        flexDirection: 'column',
        overflow:      'hidden',
      }}>
        {/* Header */}
        <div style={{
          padding:        '14px 20px',
          borderBottom:   `1px solid ${COLORS.border}`,
          display:        'flex',
          alignItems:     'center',
          justifyContent: 'space-between',
          flexShrink:     0,
          background:     COLORS.mintGlow2,
        }}>
          <div>
            <span style={{
              fontFamily:    'var(--font-display)',
              fontWeight:    '800',
              fontSize:      '16px',
              color:         COLORS.mint,
              letterSpacing: '0.03em',
            }}>
              🎒 INVENTORY
            </span>
            {total > 0 && (
              <span style={{
                marginLeft:  '10px',
                fontSize:    '11px',
                fontFamily:  'var(--font-mono)',
                color:       COLORS.textSecondary,
              }}>
                {total} item{total !== 1 ? 's' : ''}
              </span>
            )}
          </div>
          <div style={{ display:'flex', gap:'8px', alignItems:'center' }}>
            <button
              onClick={loadInventory}
              title="Refresh"
              style={{
                background:  'transparent',
                border:      `1px solid ${COLORS.border}`,
                borderRadius: RADIUS.sm,
                color:       COLORS.textMuted,
                fontSize:    '13px',
                cursor:      'pointer',
                padding:     '3px 8px',
              }}
            >
              ↺
            </button>
            <button
              onClick={onClose}
              style={{
                background:  'transparent',
                border:      'none',
                color:       COLORS.textMuted,
                fontSize:    '18px',
                cursor:      'pointer',
                padding:     '2px 6px',
                lineHeight:  1,
              }}
            >
              ✕
            </button>
          </div>
        </div>

        {/* Content */}
        <div style={{ overflowY:'auto', padding:'16px', flex:1 }}>
          {loading ? (
            <div style={{
              display:'flex', justifyContent:'center', padding:'40px',
              color:COLORS.textMuted, fontFamily:'var(--font-mono)', fontSize:'12px',
            }}>
              Loading inventory…
            </div>
          ) : error ? (
            <div style={{
              display:'flex', flexDirection:'column', alignItems:'center',
              gap:'12px', padding:'40px',
            }}>
              <span style={{ fontSize:'13px', fontFamily:'var(--font-mono)', color:COLORS.danger }}>
                {error}
              </span>
              <button
                onClick={loadInventory}
                style={{
                  padding:'6px 18px', fontSize:'12px', fontFamily:'var(--font-mono)',
                  color:COLORS.mint, background:COLORS.mintGlow,
                  border:`1px solid ${COLORS.borderMint}`, borderRadius:RADIUS.sm, cursor:'pointer',
                }}
              >
                Retry
              </button>
            </div>
          ) : items.length === 0 ? (
            <div style={{
              display:'flex', flexDirection:'column', alignItems:'center',
              justifyContent:'center', padding:'40px', gap:'10px',
            }}>
              <span style={{ fontSize:'32px' }}>📭</span>
              <span style={{
                fontFamily:'var(--font-mono)', fontSize:'13px', color:COLORS.textMuted,
              }}>
                Empty. Try /shop.
              </span>
            </div>
          ) : (
            <div style={{
              display:'grid', gridTemplateColumns:'repeat(2, 1fr)', gap:'10px',
            }}>
              {items.map((item, i) => (
                <ItemCard
                  key={item.item_id || i}
                  item={item}
                  chatId={chatId}
                  onClose={onClose}
                />
              ))}
            </div>
          )}
        </div>

        {/* Footer */}
        <div style={{
          padding:'10px 20px', borderTop:`1px solid ${COLORS.border}`,
          display:'flex', justifyContent:'flex-end', flexShrink:0,
        }}>
          <button
            onClick={() => {
              if (state.user && chatId) sendMessage(chatId, state.user.id, '/shop');
              onClose();
            }}
            style={{
              padding:'7px 18px', fontSize:'12px', fontFamily:'var(--font-mono)',
              color:COLORS.mint, background:COLORS.mintGlow,
              border:`1px solid ${COLORS.borderMint}`, borderRadius:RADIUS.sm, cursor:'pointer',
            }}
          >
            Open Shop →
          </button>
        </div>
      </div>
    </div>
  );
}
