/**
 * components/BotCard.js
 * Renders bot response cards: title, fields grid, interactive buttons.
 * Personality tag controls the accent color + icon strip.
 */

import React, { useState } from 'react';
import { COLORS, PERSONALITY_META, RADIUS, SHADOW } from '../styles/theme';
import { sendActionCallback } from '../socket/socket';
import { useStore } from '../store/userStore';

// ─── Personality strip ────────────────────────────────────────────────────────
function PersonalityBadge({ tag }) {
  const meta = PERSONALITY_META[tag] || PERSONALITY_META.neutral_witty;
  return (
    <span style={{
      display:      'inline-flex',
      alignItems:   'center',
      gap:          '4px',
      fontSize:     '10px',
      fontFamily:   'var(--font-mono)',
      color:        meta.color,
      background:   `${meta.color}18`,
      border:       `1px solid ${meta.color}44`,
      borderRadius: RADIUS.pill,
      padding:      '2px 8px',
      letterSpacing:'0.04em',
      textTransform:'uppercase',
    }}>
      {meta.icon} {meta.label}
    </span>
  );
}

// ─── Field row ────────────────────────────────────────────────────────────────
function FieldRow({ label, value, accent }) {
  const isPositive = String(value).startsWith('+');
  const isNegative = String(value).startsWith('-');
  const valueColor = isPositive
    ? COLORS.mint
    : isNegative
    ? COLORS.danger
    : (accent || COLORS.textPrimary);

  return (
    <div style={{
      display:       'flex',
      justifyContent:'space-between',
      alignItems:    'center',
      padding:       '6px 0',
      borderBottom:  `1px solid ${COLORS.border}`,
    }}>
      <span style={{
        fontSize:   '11px',
        fontFamily: 'var(--font-mono)',
        color:      COLORS.textSecondary,
        letterSpacing: '0.04em',
        textTransform: 'uppercase',
      }}>
        {label}
      </span>
      <span style={{
        fontSize:   '13px',
        fontFamily: 'var(--font-mono)',
        color:      valueColor,
        fontWeight: isPositive || isNegative ? '500' : '400',
      }}>
        {value}
      </span>
    </div>
  );
}

// ─── Action button ─────────────────────────────────────────────────────────────
function ActionButton({ label, action, chatId, messageId, onSent }) {
  const { state } = useStore();
  const [loading, setLoading] = useState(false);

  function handleClick() {
    if (loading || !state.user) return;
    setLoading(true);
    sendActionCallback(action, state.user.id, chatId, messageId);
    setTimeout(() => setLoading(false), 800);
    onSent?.(action);
  }

  return (
    <button
      onClick={handleClick}
      disabled={loading}
      style={{
        display:       'flex',
        alignItems:    'center',
        justifyContent:'center',
        padding:       '7px 14px',
        fontSize:      '11px',
        fontFamily:    'var(--font-mono)',
        fontWeight:    '500',
        letterSpacing: '0.06em',
        textTransform: 'uppercase',
        color:         loading ? COLORS.textMuted : COLORS.mint,
        background:    loading ? COLORS.bg4 : COLORS.mintGlow,
        border:        `1px solid ${loading ? COLORS.border : COLORS.borderMint}`,
        borderRadius:  RADIUS.sm,
        cursor:        loading ? 'default' : 'pointer',
        transition:    'all 0.15s ease',
        whiteSpace:    'nowrap',
      }}
      onMouseEnter={e => {
        if (!loading) {
          e.currentTarget.style.background = `${COLORS.mint}22`;
          e.currentTarget.style.boxShadow  = SHADOW.mint;
        }
      }}
      onMouseLeave={e => {
        e.currentTarget.style.background = loading ? COLORS.bg4 : COLORS.mintGlow;
        e.currentTarget.style.boxShadow  = 'none';
      }}
    >
      {loading ? '···' : label}
    </button>
  );
}

// ─── Main BotCard ──────────────────────────────────────────────────────────────
export default function BotCard({ card, personality, chatId, messageId }) {
  if (!card) return null;

  const personalityMeta = PERSONALITY_META[personality] || PERSONALITY_META.neutral_witty;
  const accentColor     = personalityMeta.color;

  return (
    <div style={{
      background:   COLORS.bg3,
      border:       `1px solid ${COLORS.border}`,
      borderLeft:   `3px solid ${accentColor}`,
      borderRadius: RADIUS.lg,
      overflow:     'hidden',
      boxShadow:    SHADOW.card,
      maxWidth:     '380px',
      width:        '100%',
    }}>
      {/* Header */}
      <div style={{
        padding:       '10px 14px 8px',
        borderBottom:  `1px solid ${COLORS.border}`,
        display:       'flex',
        alignItems:    'center',
        justifyContent:'space-between',
        gap:           '8px',
        background:    `${accentColor}08`,
      }}>
        <span style={{
          fontSize:   '13px',
          fontFamily: 'var(--font-display)',
          fontWeight: '700',
          color:      COLORS.textPrimary,
          letterSpacing: '0.01em',
        }}>
          {card.title}
        </span>
        {personality && <PersonalityBadge tag={personality} />}
      </div>

      {/* Fields */}
      {card.fields?.length > 0 && (
        <div style={{ padding: '4px 14px 8px' }}>
          {card.fields.map((f, i) => (
            <FieldRow
              key={i}
              label={f.label}
              value={f.value}
              accent={accentColor}
            />
          ))}
        </div>
      )}

      {/* Buttons */}
      {card.buttons?.length > 0 && (
        <div style={{
          display:   'flex',
          flexWrap:  'wrap',
          gap:       '6px',
          padding:   '8px 14px 12px',
          borderTop: `1px solid ${COLORS.border}`,
        }}>
          {card.buttons.map((btn, i) => (
            <ActionButton
              key={i}
              label={btn.label}
              action={btn.action}
              chatId={chatId}
              messageId={messageId}
            />
          ))}
        </div>
      )}
    </div>
  );
}
