/**
 * components/InboxModal.js
 *
 * Fix #6 — Ghost Private Messages:
 *   Critical notifications (lottery wins, purchase receipts, item effects)
 *   arrive via the private_message socket event. Previously they were appended
 *   to state.privateMessages and shown as a 4-second toast — after which the
 *   data was inaccessible. This modal gives those messages a permanent home.
 *
 * Trigger: click the inbox icon (🔔) in App.js user pill — shown with an
 * unread badge count that clears when the modal is opened.
 */

import React, { useEffect } from 'react';
import { COLORS, RADIUS, SHADOW } from '../styles/theme';
import { useStore, A } from '../store/userStore';
import { formatTime } from '../utils/formatters';
import BotCard from './BotCard';

// ─── Single inbox entry ───────────────────────────────────────────────────────

function InboxEntry({ msg }) {
  const card        = msg.metadata?.card;
  const personality = msg.metadata?.personality;

  return (
    <div style={{
      padding:       '12px 16px',
      background:    COLORS.bg3,
      border:        `1px solid ${COLORS.border}`,
      borderRadius:  RADIUS.md,
      display:       'flex',
      flexDirection: 'column',
      gap:           '8px',
    }}>
      {/* Meta row */}
      <div style={{ display:'flex', alignItems:'center', justifyContent:'space-between' }}>
        <span style={{
          fontSize:   '11px',
          fontFamily: 'var(--font-mono)',
          color:      COLORS.mint,
          display:    'flex',
          alignItems: 'center',
          gap:        '5px',
        }}>
          🤖 GameBot
          <span style={{
            background:   `${COLORS.blue}18`,
            border:       `1px solid ${COLORS.blue}44`,
            borderRadius: RADIUS.pill,
            padding:      '1px 7px',
            color:        COLORS.blue,
            fontSize:     '9px',
            letterSpacing:'0.06em',
            textTransform:'uppercase',
          }}>
            Private
          </span>
        </span>
        <span style={{ fontSize:'10px', fontFamily:'var(--font-mono)', color:COLORS.textMuted }}>
          {formatTime(msg.timestamp)}
        </span>
      </div>

      {/* Text content */}
      {msg.content && (
        <div style={{
          fontSize:   '13px',
          fontFamily: 'var(--font-body)',
          color:      COLORS.textPrimary,
          lineHeight: '1.5',
        }}>
          {msg.content}
        </div>
      )}

      {/* Structured card */}
      {card && (
        <BotCard
          card={card}
          personality={personality}
          chatId={null}          // inbox cards are read-only — no action callbacks
          messageId={msg.id}
        />
      )}
    </div>
  );
}

// ─── Main modal ───────────────────────────────────────────────────────────────

export default function InboxModal({ onClose }) {
  const { state, dispatch } = useStore();
  const messages = [...(state.privateMessages || [])].reverse(); // newest first

  // Mark inbox as read when opened
  useEffect(() => {
    dispatch({ type: A.MARK_INBOX_READ });
  }, [dispatch]);

  return (
    <div
      style={{
        position:       'fixed',
        inset:          0,
        background:     'rgba(7,8,13,0.85)',
        display:        'flex',
        alignItems:     'center',
        justifyContent: 'center',
        zIndex:         200,
        backdropFilter: 'blur(4px)',
      }}
      onClick={e => { if (e.target === e.currentTarget) onClose(); }}
    >
      <div style={{
        width:         '500px',
        maxHeight:     '78vh',
        background:    COLORS.bg2,
        border:        `1px solid ${COLORS.border}`,
        borderTop:     `3px solid ${COLORS.blue}`,
        borderRadius:  RADIUS.xl,
        boxShadow:     `${SHADOW.card}, ${SHADOW.blue}`,
        display:       'flex',
        flexDirection: 'column',
        overflow:      'hidden',
      }}>
        {/* Header */}
        <div style={{
          padding:        '14px 20px',
          borderBottom:   `1px solid ${COLORS.border}`,
          display:        'flex',
          alignItems:     'center',
          justifyContent: 'space-between',
          background:     `${COLORS.blue}08`,
          flexShrink:     0,
        }}>
          <div>
            <span style={{
              fontFamily:    'var(--font-display)',
              fontWeight:    '800',
              fontSize:      '16px',
              color:         COLORS.blue,
              letterSpacing: '0.03em',
            }}>
              📬 INBOX
            </span>
            <span style={{
              marginLeft:  '10px',
              fontSize:    '11px',
              fontFamily:  'var(--font-mono)',
              color:       COLORS.textSecondary,
            }}>
              {messages.length} message{messages.length !== 1 ? 's' : ''}
            </span>
          </div>
          <button
            onClick={onClose}
            style={{
              background:'transparent', border:'none',
              color:COLORS.textMuted, fontSize:'18px', cursor:'pointer', padding:'2px 6px',
            }}
          >
            ✕
          </button>
        </div>

        {/* Message list */}
        <div style={{ overflowY:'auto', padding:'14px 16px', flex:1, display:'flex', flexDirection:'column', gap:'10px' }}>
          {messages.length === 0 ? (
            <div style={{
              display:'flex', flexDirection:'column', alignItems:'center',
              justifyContent:'center', padding:'48px', gap:'12px',
            }}>
              <span style={{ fontSize:'36px' }}>📭</span>
              <span style={{
                fontFamily:'var(--font-mono)', fontSize:'12px', color:COLORS.textMuted,
              }}>
                No messages yet. Win a lottery. Buy something.
              </span>
            </div>
          ) : (
            messages.map((msg, i) => (
              <InboxEntry key={msg.id || i} msg={msg} />
            ))
          )}
        </div>

        {/* Footer note */}
        <div style={{
          padding:'8px 20px', borderTop:`1px solid ${COLORS.border}`,
          flexShrink:0,
        }}>
          <span style={{
            fontSize:'10px', fontFamily:'var(--font-mono)', color:COLORS.textMuted,
          }}>
            Messages are kept for this session only. Receipts &amp; wins appear here.
          </span>
        </div>
      </div>
    </div>
  );
}
