/**
 * store/userStore.js
 * Global app state via React Context + useReducer.
 * Keeps: auth, current chat, messages per chat, notifications.
 *
 * Usage:
 *   import { useStore, StoreProvider } from './store/userStore';
 *   const { state, dispatch } = useStore();
 */

import React, { createContext, useContext, useReducer, useCallback } from 'react';

// ─── Action types ─────────────────────────────────────────────────────────────
export const A = {
  SET_USER:             'SET_USER',
  SET_CHATS:            'SET_CHATS',
  SET_CURRENT_CHAT:     'SET_CURRENT_CHAT',
  SET_HISTORY:          'SET_HISTORY',
  APPEND_MESSAGE:       'APPEND_MESSAGE',
  APPEND_PRIVATE:       'APPEND_PRIVATE',
  MARK_INBOX_READ:      'MARK_INBOX_READ',   // Fix #6: clears unread badge
  SET_INVENTORY:        'SET_INVENTORY',
  SET_CONNECTED:        'SET_CONNECTED',
  ADD_TOAST:            'ADD_TOAST',
  REMOVE_TOAST:         'REMOVE_TOAST',
  SET_HOMIESPHERE_OPT:  'SET_HOMIESPHERE_OPT',
  LOGOUT:               'LOGOUT',
};

// ─── Initial state ────────────────────────────────────────────────────────────
const INITIAL = {
  user:              null,
  chats:             [],
  currentChatId:     null,
  messages:          {},
  privateMessages:   [],
  inboxUnread:       0,      // Fix #6: badge count, increments on each private_message
  inventory:         [],
  connected:         false,
  toasts:            [],
  homisphereOptIn:   true,
};

// ─── Reducer ──────────────────────────────────────────────────────────────────
function reducer(state, action) {
  switch (action.type) {

    case A.SET_USER:
      return { ...state, user: action.payload };

    case A.SET_CHATS:
      return { ...state, chats: action.payload };

    case A.SET_CURRENT_CHAT:
      return { ...state, currentChatId: action.payload };

    case A.SET_HISTORY: {
      const { chatId, messages } = action.payload;
      return {
        ...state,
        messages: { ...state.messages, [chatId]: messages },
      };
    }

    case A.APPEND_MESSAGE: {
      const { chatId, message } = action.payload;
      const existing = state.messages[chatId] || [];
      // Deduplicate by message id
      if (existing.some(m => m.id === message.id)) return state;
      return {
        ...state,
        messages: {
          ...state.messages,
          [chatId]: [...existing, message],
        },
      };
    }

    case A.APPEND_PRIVATE:
      return {
        ...state,
        privateMessages: [...state.privateMessages, action.payload],
        inboxUnread:     state.inboxUnread + 1,   // Fix #6: bump badge
      };

    case A.MARK_INBOX_READ:
      return { ...state, inboxUnread: 0 };

    case A.SET_INVENTORY:
      return { ...state, inventory: action.payload };

    case A.SET_CONNECTED:
      return { ...state, connected: action.payload };

    case A.ADD_TOAST: {
      const toast = { id: Date.now(), ...action.payload };
      return { ...state, toasts: [...state.toasts, toast] };
    }

    case A.REMOVE_TOAST:
      return { ...state, toasts: state.toasts.filter(t => t.id !== action.payload) };

    case A.SET_HOMIESPHERE_OPT:
      return { ...state, homiesphereOptIn: action.payload };

    case A.LOGOUT:
      return { ...INITIAL };

    default:
      return state;
  }
}

// ─── Context ──────────────────────────────────────────────────────────────────
const StoreContext = createContext(null);

export function StoreProvider({ children }) {
  const [state, dispatch] = useReducer(reducer, INITIAL);

  /**
   * Convenience: add a toast that auto-removes after `ms` milliseconds.
   */
  const toast = useCallback((type, text, ms = 4000) => {
    const id = Date.now();
    dispatch({ type: A.ADD_TOAST, payload: { id, type, text } });
    setTimeout(() => dispatch({ type: A.REMOVE_TOAST, payload: id }), ms);
  }, []);

  return (
    <StoreContext.Provider value={{ state, dispatch, toast }}>
      {children}
    </StoreContext.Provider>
  );
}

export function useStore() {
  const ctx = useContext(StoreContext);
  if (!ctx) throw new Error('useStore must be used inside <StoreProvider>');
  return ctx;
}

// ─── Selectors ────────────────────────────────────────────────────────────────
export const selectCurrentMessages = (state) =>
  state.currentChatId ? (state.messages[state.currentChatId] || []) : [];

export const selectCurrentChat = (state) =>
  state.chats.find(c => c.id === state.currentChatId) || null;
