/**
 * components/ChatsList.js
 * Left sidebar: chat list + connection status + Homiesphere toggle.
 */

import React from 'react';
import { COLORS, RADIUS, SHADOW } from '../styles/theme';
import { useStore, A } from '../store/userStore';
import { joinChat, leaveChat } from '../socket/socket';
import { userColor } from '../utils/formatters';

// ─── Chat row ─────────────────────────────────────────────────────────────────
function ChatRow({ chat, isActive, onClick }) {
  const color = chat.type === 'global' ? COLORS.mint : userColor(chat.id);

  return (
    <button
      onClick={onClick}
      style={{
        display:      'flex',
        alignItems:   'center',
        gap:          '10px',
        width:        '100%',
        padding:      '9px 14px',
        background:   isActive ? COLORS.mintGlow : 'transparent',
        border:       'none',
        borderLeft:   `3px solid ${isActive ? COLORS.mint : 'transparent'}`,
        borderRadius: `0 ${RADIUS.sm} ${RADIUS.sm} 0`,
        cursor:       'pointer',
        transition:   'all 0.12s',
        textAlign:    'left',
      }}
      onMouseEnter={e => { if (!isActive) e.currentTarget.style.background = COLORS.bg3; }}
      onMouseLeave={e => { if (!isActive) e.currentTarget.style.background = 'transparent'; }}
    >
      {/* Icon */}
      <div style={{
        width:          30,
        height:         30,
        borderRadius:   RADIUS.sm,
        background:     `${color}18`,
        border:         `1px solid ${color}33`,
        display:        'flex',
        alignItems:     'center',
        justifyContent: 'center',
        fontSize:       '13px',
        flexShrink:     0,
      }}>
        {chat.type === 'global' ? '🌐' : chat.type === 'gang' ? '🔱' : '💬'}
      </div>

      {/* Name + unread */}
      <div style={{ flex: 1, minWidth: 0 }}>
        <div style={{
          fontSize:     '13px',
          fontFamily:   'var(--font-display)',
          fontWeight:   isActive ? '600' : '400',
          color:        isActive ? COLORS.mint : COLORS.textPrimary,
          whiteSpace:   'nowrap',
          overflow:     'hidden',
          textOverflow: 'ellipsis',
        }}>
          {chat.name}
        </div>
        {chat.lastMessage && (
          <div style={{
            fontSize:     '11px',
            fontFamily:   'var(--font-body)',
            color:        COLORS.textMuted,
            whiteSpace:   'nowrap',
            overflow:     'hidden',
            textOverflow: 'ellipsis',
            marginTop:    '2px',
          }}>
            {chat.lastMessage}
          </div>
        )}
      </div>

      {/* Unread badge */}
      {chat.unread > 0 && (
        <div style={{
          minWidth:       '18px',
          height:         '18px',
          borderRadius:   RADIUS.pill,
          background:     COLORS.mint,
          color:          COLORS.bg0,
          fontSize:       '10px',
          fontFamily:     'var(--font-mono)',
          fontWeight:     '700',
          display:        'flex',
          alignItems:     'center',
          justifyContent: 'center',
          padding:        '0 5px',
          flexShrink:     0,
        }}>
          {chat.unread > 99 ? '99+' : chat.unread}
        </div>
      )}
    </button>
  );
}

// ─── Main sidebar ─────────────────────────────────────────────────────────────
export default function ChatsList() {
  const { state, dispatch } = useStore();

  function selectChat(chatId) {
    dispatch({ type: A.SET_CURRENT_CHAT, payload: chatId });
  }

  function toggleHomiesphere() {
    const newVal = !state.homiesphereOptIn;
    dispatch({ type: A.SET_HOMIESPHERE_OPT, payload: newVal });
    const homiesphereChat = state.chats.find(c => c.type === 'global');
    if (homiesphereChat) {
      if (newVal) joinChat(homiesphereChat.id);
      else        leaveChat(homiesphereChat.id);
    }
  }

  const globals = state.chats.filter(c => c.type === 'global');
  const gangs   = state.chats.filter(c => c.type === 'gang');
  const dms     = state.chats.filter(c => c.type === 'dm');

  function Section({ label, chats }) {
    if (!chats.length) return null;
    return (
      <div style={{ marginBottom: '8px' }}>
        <div style={{
          padding:      '6px 14px 4px',
          fontSize:     '10px',
          fontFamily:   'var(--font-mono)',
          color:        COLORS.textMuted,
          letterSpacing:'0.1em',
          textTransform:'uppercase',
        }}>
          {label}
        </div>
        {chats.map(chat => (
          <ChatRow
            key={chat.id}
            chat={chat}
            isActive={state.currentChatId === chat.id}
            onClick={() => selectChat(chat.id)}
          />
        ))}
      </div>
    );
  }

  return (
    <div style={{
      width:        '230px',
      background:   COLORS.bg1,
      borderRight:  `1px solid ${COLORS.border}`,
      display:      'flex',
      flexDirection:'column',
      overflow:     'hidden',
      flexShrink:   0,
    }}>
      {/* Brand header */}
      <div style={{
        padding:      '16px 16px 14px',
        borderBottom: `1px solid ${COLORS.border}`,
        display:      'flex',
        alignItems:   'center',
        gap:          '8px',
      }}>
        <div style={{
          width:          32,
          height:         32,
          borderRadius:   RADIUS.sm,
          background:     COLORS.mintGlow,
          border:         `1px solid ${COLORS.borderMint}`,
          display:        'flex',
          alignItems:     'center',
          justifyContent: 'center',
          fontSize:       '16px',
          boxShadow:      SHADOW.mint,
        }}>
          🔱
        </div>
        <div>
          <div style={{
            fontFamily:   'var(--font-display)',
            fontWeight:   '800',
            fontSize:     '14px',
            color:        COLORS.mint,
            letterSpacing:'0.03em',
          }}>
            HOMIESPHERE
          </div>
          <div style={{
            fontSize:   '10px',
            fontFamily: 'var(--font-mono)',
            color:      state.connected ? COLORS.mint : COLORS.warning,
          }}>
            {state.connected ? '● connected' : '○ connecting…'}
          </div>
        </div>
      </div>

      {/* Chat list */}
      <div style={{ flex: 1, overflowY: 'auto', paddingTop: '8px' }}>
        <Section label="Global"  chats={globals} />
        <Section label="Gang"    chats={gangs}   />
        <Section label="Direct"  chats={dms}     />
      </div>

      {/* Homiesphere toggle */}
      <div style={{
        padding:   '10px 14px',
        borderTop: `1px solid ${COLORS.border}`,
      }}>
        <button
          onClick={toggleHomiesphere}
          style={{
            display:      'flex',
            alignItems:   'center',
            justifyContent:'space-between',
            width:        '100%',
            padding:      '7px 10px',
            background:   COLORS.bg3,
            border:       `1px solid ${COLORS.border}`,
            borderRadius: RADIUS.sm,
            cursor:       'pointer',
          }}
        >
          <span style={{
            fontSize:   '11px',
            fontFamily: 'var(--font-mono)',
            color:      COLORS.textSecondary,
          }}>
            🌐 Homiesphere
          </span>
          <div style={{
            width:       '28px',
            height:      '15px',
            borderRadius:RADIUS.pill,
            background:  state.homiesphereOptIn ? COLORS.mint : COLORS.bg4,
            border:      `1px solid ${state.homiesphereOptIn ? COLORS.mint : COLORS.border}`,
            position:    'relative',
            transition:  'all 0.2s',
          }}>
            <div style={{
              position:   'absolute',
              top:        '2px',
              left:       state.homiesphereOptIn ? '14px' : '2px',
              width:      '9px',
              height:     '9px',
              borderRadius:'50%',
              background: state.homiesphereOptIn ? COLORS.bg0 : COLORS.textMuted,
              transition: 'left 0.2s',
            }} />
          </div>
        </button>
      </div>
    </div>
  );
}
