/**
 * components/LeaderboardModal.js
 * Leaderboard overlay — fetches via REST, highlights current user's rank.
 */

import React, { useEffect, useState } from 'react';
import { COLORS, RADIUS, SHADOW } from '../styles/theme';
import { fetchLeaderboard } from '../api/restHelpers';
import { useStore } from '../store/userStore';
import { formatCoins } from '../utils/formatters';

const MEDALS = ['🥇', '🥈', '🥉'];

function RankRow({ entry, rank, isSelf }) {
  const medal = rank <= 3 ? MEDALS[rank - 1] : null;
  const selfStyle = isSelf ? {
    background:  `${COLORS.mint}10`,
    borderColor: `${COLORS.borderMint}`,
    boxShadow:   `0 0 8px ${COLORS.mintGlow}`,
  } : {};

  return (
    <div style={{
      display:      'flex',
      alignItems:   'center',
      gap:          '12px',
      padding:      '9px 14px',
      background:   COLORS.bg3,
      border:       `1px solid ${COLORS.border}`,
      borderRadius: RADIUS.sm,
      transition:   'all 0.1s',
      ...selfStyle,
    }}>
      {/* Rank */}
      <div style={{
        width:          30,
        textAlign:      'center',
        fontSize:       medal ? '18px' : '12px',
        fontFamily:     'var(--font-mono)',
        color:          medal ? 'inherit' : COLORS.textSecondary,
        fontWeight:     '600',
        flexShrink:     0,
      }}>
        {medal || `#${rank}`}
      </div>

      {/* Username */}
      <div style={{
        flex:         1,
        fontSize:     '13px',
        fontFamily:   'var(--font-display)',
        fontWeight:   isSelf ? '700' : '500',
        color:        isSelf ? COLORS.mint : COLORS.textPrimary,
        whiteSpace:   'nowrap',
        overflow:     'hidden',
        textOverflow: 'ellipsis',
      }}>
        {entry.username}
        {isSelf && <span style={{ fontSize:'10px', color: COLORS.mint, marginLeft:'6px' }}>← you</span>}
      </div>

      {/* Level */}
      <div style={{
        fontSize:   '11px',
        fontFamily: 'var(--font-mono)',
        color:      COLORS.textSecondary,
        flexShrink: 0,
      }}>
        Lv {entry.level}
      </div>

      {/* Score */}
      <div style={{
        fontSize:   '13px',
        fontFamily: 'var(--font-mono)',
        fontWeight: '600',
        color:      COLORS.blue,
        flexShrink: 0,
        minWidth:   '70px',
        textAlign:  'right',
      }}>
        {formatCoins(entry.score)} pts
      </div>
    </div>
  );
}

export default function LeaderboardModal({ onClose }) {
  const { state }                 = useStore();
  const [entries, setEntries]     = useState([]);
  const [season, setSeason]       = useState(null);
  const [total, setTotal]         = useState(0);
  const [page, setPage]           = useState(1);
  const [loading, setLoading]     = useState(true);

  async function load(p = 1) {
    setLoading(true);
    try {
      const data = await fetchLeaderboard(p);
      setEntries(data.entries || []);
      setSeason(data.season);
      setTotal(data.total || 0);
      setPage(p);
    } catch (err) {
      console.error('[Leaderboard] fetch failed:', err);
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => { load(1); }, []);

  const totalPages = Math.max(1, Math.ceil(total / 15));

  return (
    <div style={{
      position:       'fixed',
      inset:          0,
      background:     'rgba(7,8,13,0.85)',
      display:        'flex',
      alignItems:     'center',
      justifyContent: 'center',
      zIndex:         200,
      backdropFilter: 'blur(4px)',
    }}
      onClick={e => { if (e.target === e.currentTarget) onClose(); }}
    >
      <div style={{
        width:        '500px',
        maxHeight:    '80vh',
        background:   COLORS.bg2,
        border:       `1px solid ${COLORS.border}`,
        borderTop:    `3px solid ${COLORS.blue}`,
        borderRadius: RADIUS.xl,
        boxShadow:    `${SHADOW.card}, ${SHADOW.blue}`,
        display:      'flex',
        flexDirection:'column',
        overflow:     'hidden',
      }}>
        {/* Header */}
        <div style={{
          padding:       '14px 20px',
          borderBottom:  `1px solid ${COLORS.border}`,
          display:       'flex',
          alignItems:    'center',
          justifyContent:'space-between',
          background:    `${COLORS.blue}08`,
          flexShrink:    0,
        }}>
          <div>
            <div style={{
              fontFamily:   'var(--font-display)',
              fontWeight:   '800',
              fontSize:     '16px',
              color:        COLORS.blue,
              letterSpacing:'0.03em',
            }}>
              🏆 LEADERBOARD
            </div>
            {season && (
              <div style={{
                fontSize:   '11px',
                fontFamily: 'var(--font-mono)',
                color:      COLORS.textSecondary,
                marginTop:  '2px',
              }}>
                {season.name}
              </div>
            )}
          </div>
          <button
            onClick={onClose}
            style={{
              background: 'transparent',
              border:     'none',
              color:      COLORS.textMuted,
              fontSize:   '18px',
              cursor:     'pointer',
              padding:    '2px 6px',
            }}
          >
            ✕
          </button>
        </div>

        {/* List */}
        <div style={{
          overflowY: 'auto',
          padding:   '12px 16px',
          flex:      1,
          display:   'flex',
          flexDirection:'column',
          gap:       '4px',
        }}>
          {loading ? (
            <div style={{
              display:        'flex',
              justifyContent: 'center',
              padding:        '40px',
              color:          COLORS.textMuted,
              fontFamily:     'var(--font-mono)',
              fontSize:       '12px',
            }}>
              Loading rankings…
            </div>
          ) : entries.length === 0 ? (
            <div style={{
              textAlign: 'center',
              padding:   '40px',
              color:     COLORS.textMuted,
              fontFamily:'var(--font-mono)',
              fontSize:  '12px',
            }}>
              No entries yet. Be the first.
            </div>
          ) : (
            entries.map((entry, i) => {
              const rank   = (page - 1) * 15 + i + 1;
              const isSelf = entry.user_id === state.user?.id;
              return (
                <RankRow key={entry.user_id} entry={entry} rank={rank} isSelf={isSelf} />
              );
            })
          )}
        </div>

        {/* Pagination */}
        <div style={{
          padding:       '10px 16px',
          borderTop:     `1px solid ${COLORS.border}`,
          display:       'flex',
          alignItems:    'center',
          justifyContent:'space-between',
          flexShrink:    0,
        }}>
          <span style={{
            fontSize:   '11px',
            fontFamily: 'var(--font-mono)',
            color:      COLORS.textMuted,
          }}>
            {total} players · Page {page}/{totalPages}
          </span>
          <div style={{ display:'flex', gap:'6px' }}>
            <button
              onClick={() => load(page - 1)}
              disabled={page <= 1 || loading}
              style={{
                padding:      '5px 12px',
                fontSize:     '11px',
                fontFamily:   'var(--font-mono)',
                color:        page <= 1 ? COLORS.textMuted : COLORS.blue,
                background:   COLORS.bg3,
                border:       `1px solid ${COLORS.border}`,
                borderRadius: RADIUS.sm,
                cursor:       page <= 1 ? 'default' : 'pointer',
              }}
            >
              ◀
            </button>
            <button
              onClick={() => load(page + 1)}
              disabled={page >= totalPages || loading}
              style={{
                padding:      '5px 12px',
                fontSize:     '11px',
                fontFamily:   'var(--font-mono)',
                color:        page >= totalPages ? COLORS.textMuted : COLORS.blue,
                background:   COLORS.bg3,
                border:       `1px solid ${COLORS.border}`,
                borderRadius: RADIUS.sm,
                cursor:       page >= totalPages ? 'default' : 'pointer',
              }}
            >
              ▶
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}
