/**
 * socket/socket.js
 * Socket.IO client singleton.
 *
 * Usage:
 *   import { connectSocket, getSocket, disconnectSocket } from './socket';
 *   connectSocket(token, { onMessage, onPrivateMessage, onInventoryUpdated, onError });
 */

import { io } from 'socket.io-client';

const SERVER = (() => {
  const url = process.env.REACT_APP_SERVER_URL;
  // Fix: fail loudly in production if the env var is not set.
  // A missing value means Socket.IO silently connects to localhost, which
  // works on dev but causes invisible failures on every deployed environment.
  if (!url && process.env.NODE_ENV === 'production') {
    throw new Error(
      '[socket.js] REACT_APP_SERVER_URL is not set. ' +
      'Copy .env.example to .env and set this value before building.'
    );
  }
  return url || 'http://localhost:3001';
})();

let _socket = null;

/**
 * Connect to the server and register all event handlers.
 *
 * @param {string} token — JWT from login
 * @param {object} handlers
 * @param {Function} handlers.onConnect
 * @param {Function} handlers.onDisconnect
 * @param {Function} handlers.onMessage           — (message) => void
 * @param {Function} handlers.onPrivateMessage    — (message) => void
 * @param {Function} handlers.onInventoryUpdated  — (payload) => void
 * @param {Function} handlers.onJoinAck           — (payload) => void
 * @param {Function} handlers.onError             — (error) => void
 * @returns {import('socket.io-client').Socket}
 */
export function connectSocket(token, handlers = {}) {
  if (_socket?.connected) return _socket;

  _socket = io(SERVER, {
    auth:                { token },
    transports:          ['websocket'],
    reconnectionAttempts: 8,
    reconnectionDelay:    1000,
    reconnectionDelayMax: 15000,
  });

  // ── Built-in ──────────────────────────────────────────────────────────────
  _socket.on('connect', () => {
    console.log('[Socket] Connected:', _socket.id);
    handlers.onConnect?.();
  });

  _socket.on('disconnect', (reason) => {
    console.warn('[Socket] Disconnected:', reason);
    handlers.onDisconnect?.(reason);
  });

  _socket.on('connect_error', (err) => {
    console.error('[Socket] Connection error:', err.message);
    handlers.onError?.({ code: 'CONNECT_ERROR', message: err.message });
  });

  // ── Server → Client events ────────────────────────────────────────────────
  _socket.on('message', (payload) => {
    handlers.onMessage?.(payload);
  });

  _socket.on('private_message', (payload) => {
    handlers.onPrivateMessage?.(payload);
  });

  _socket.on('inventory_updated', (payload) => {
    handlers.onInventoryUpdated?.(payload);
  });

  _socket.on('join_ack', (payload) => {
    handlers.onJoinAck?.(payload);
  });

  _socket.on('error', (payload) => {
    console.error('[Socket] Server error:', payload);
    handlers.onError?.(payload);
  });

  return _socket;
}

export function getSocket() {
  return _socket;
}

export function disconnectSocket() {
  if (_socket) {
    _socket.removeAllListeners();
    _socket.disconnect();
    _socket = null;
  }
}

// ─── Emit helpers — call these instead of socket.emit() directly ──────────────

/**
 * Send a chat message or command.
 * @param {string} chatId
 * @param {string} userId
 * @param {string} text
 */
export function sendMessage(chatId, userId, text) {
  _socket?.emit('send_message', {
    chat_id:   chatId,
    user_id:   userId,
    text:      text.trim(),
    timestamp: Date.now(),
  });
}

/**
 * Send an action callback (button tap on a bot card).
 * @param {string} actionId
 * @param {string} userId
 * @param {string} chatId
 * @param {string} [sourceMessageId]
 */
export function sendActionCallback(actionId, userId, chatId, sourceMessageId) {
  _socket?.emit('action_callback', {
    actionId,
    userId,
    chatId,
    meta: sourceMessageId ? { sourceMessageId } : {},
  });
}

/**
 * Join a chat room.
 * @param {string} chatId
 */
export function joinChat(chatId) {
  _socket?.emit('join_chat', { chat_id: chatId });
}

/**
 * Leave a chat room (e.g., opt-out of Homiesphere).
 * @param {string} chatId
 */
export function leaveChat(chatId) {
  _socket?.emit('leave_chat', { chat_id: chatId });
}

/**
 * Emit a typing indicator.
 * @param {string} chatId
 * @param {string} userId
 */
export function emitTyping(chatId, userId) {
  _socket?.emit('typing', { chat_id: chatId, user_id: userId });
}
