/**
 * components/HomeScreen.js
 * Login + Register screen — shown when not authenticated.
 * Toggle between the two modes with the tab switcher.
 */

import React, { useState } from 'react';
import { COLORS, RADIUS, SHADOW } from '../styles/theme';
import { login, register } from '../api/auth';
import { useStore } from '../store/userStore';

export default function HomeScreen({ onLogin }) {
  const { toast }                     = useStore();
  const [mode, setMode]               = useState('login'); // 'login' | 'register'
  const [username, setUsername]       = useState('');
  const [password, setPassword]       = useState('');
  const [confirmPassword, setConfirm] = useState('');
  const [loading, setLoading]         = useState(false);

  async function handleSubmit(e) {
    e.preventDefault();
    if (!username.trim() || !password.trim()) return;

    if (mode === 'register') {
      if (password !== confirmPassword) {
        toast('error', 'Passwords do not match.');
        return;
      }
      if (password.length < 6) {
        toast('error', 'Password must be at least 6 characters.');
        return;
      }
    }

    setLoading(true);
    try {
      const fn   = mode === 'login' ? login : register;
      const data = await fn(username.trim(), password);
      onLogin(data);
    } catch (err) {
      toast('error', err.message || (mode === 'login' ? 'Login failed' : 'Registration failed'));
    } finally {
      setLoading(false);
    }
  }

  function switchMode(next) {
    setMode(next);
    setPassword('');
    setConfirm('');
  }

  const inputStyle = {
    width:        '100%',
    padding:      '11px 14px',
    background:   COLORS.bg3,
    border:       `1px solid ${COLORS.border}`,
    borderRadius: RADIUS.md,
    fontFamily:   'var(--font-body)',
    fontSize:     '13px',
    color:        COLORS.textPrimary,
    outline:      'none',
    boxSizing:    'border-box',
    transition:   'border-color 0.15s',
  };

  const canSubmit = !loading && username.trim() && password.trim() &&
    (mode === 'login' || confirmPassword.trim());

  return (
    <div style={{
      minHeight:      '100vh',
      background:     COLORS.bg0,
      display:        'flex',
      alignItems:     'center',
      justifyContent: 'center',
      fontFamily:     'var(--font-body)',
      backgroundImage: `repeating-linear-gradient(
        0deg, transparent, transparent 2px,
        rgba(0,229,160,0.015) 2px, rgba(0,229,160,0.015) 4px
      )`,
    }}>
      <div style={{
        width:        '380px',
        padding:      '40px 36px',
        background:   COLORS.bg1,
        border:       `1px solid ${COLORS.border}`,
        borderTop:    `3px solid ${COLORS.mint}`,
        borderRadius: RADIUS.xl,
        boxShadow:    `${SHADOW.card}, ${SHADOW.mint}`,
      }}>

        {/* Logo */}
        <div style={{ textAlign: 'center', marginBottom: '28px' }}>
          <div style={{
            fontSize:    '42px',
            lineHeight:  1,
            marginBottom:'12px',
            filter:      `drop-shadow(0 0 12px ${COLORS.mint})`,
          }}>
            🔱
          </div>
          <div style={{
            fontFamily:   'var(--font-display)',
            fontWeight:   '800',
            fontSize:     '22px',
            color:        COLORS.mint,
            letterSpacing:'0.08em',
            textTransform:'uppercase',
          }}>
            Homiesphere
          </div>
          <div style={{
            fontFamily:   'var(--font-mono)',
            fontSize:     '11px',
            color:        COLORS.textMuted,
            marginTop:    '4px',
            letterSpacing:'0.05em',
          }}>
            Enter the grid
          </div>
        </div>

        {/* Mode tabs */}
        <div style={{
          display:      'flex',
          marginBottom: '24px',
          background:   COLORS.bg3,
          borderRadius: RADIUS.md,
          padding:      '3px',
          border:       `1px solid ${COLORS.border}`,
        }}>
          {['login', 'register'].map(m => (
            <button
              key={m}
              onClick={() => switchMode(m)}
              style={{
                flex:         1,
                padding:      '8px',
                border:       'none',
                borderRadius: RADIUS.sm,
                fontFamily:   'var(--font-mono)',
                fontSize:     '11px',
                fontWeight:   '600',
                letterSpacing:'0.06em',
                textTransform:'uppercase',
                cursor:       'pointer',
                transition:   'all 0.15s',
                background:   mode === m ? COLORS.mint         : 'transparent',
                color:        mode === m ? COLORS.bg0          : COLORS.textSecondary,
                boxShadow:    mode === m ? SHADOW.mint          : 'none',
              }}
            >
              {m === 'login' ? 'Sign In' : 'Register'}
            </button>
          ))}
        </div>

        {/* Form */}
        <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '14px' }}>

          {/* Username */}
          <div>
            <label style={{
              display:      'block',
              fontSize:     '10px',
              fontFamily:   'var(--font-mono)',
              color:        COLORS.textSecondary,
              letterSpacing:'0.1em',
              textTransform:'uppercase',
              marginBottom: '6px',
            }}>
              Username
            </label>
            <input
              type="text"
              value={username}
              onChange={e => setUsername(e.target.value)}
              placeholder="your_name"
              autoComplete="username"
              style={inputStyle}
              onFocus={e => e.target.style.borderColor = COLORS.borderMint}
              onBlur={e  => e.target.style.borderColor = COLORS.border}
            />
          </div>

          {/* Password */}
          <div>
            <label style={{
              display:      'block',
              fontSize:     '10px',
              fontFamily:   'var(--font-mono)',
              color:        COLORS.textSecondary,
              letterSpacing:'0.1em',
              textTransform:'uppercase',
              marginBottom: '6px',
            }}>
              Password
            </label>
            <input
              type="password"
              value={password}
              onChange={e => setPassword(e.target.value)}
              placeholder="••••••••"
              autoComplete={mode === 'login' ? 'current-password' : 'new-password'}
              style={inputStyle}
              onFocus={e => e.target.style.borderColor = COLORS.borderMint}
              onBlur={e  => e.target.style.borderColor = COLORS.border}
            />
          </div>

          {/* Confirm password — only in register mode */}
          {mode === 'register' && (
            <div>
              <label style={{
                display:      'block',
                fontSize:     '10px',
                fontFamily:   'var(--font-mono)',
                color:        COLORS.textSecondary,
                letterSpacing:'0.1em',
                textTransform:'uppercase',
                marginBottom: '6px',
              }}>
                Confirm Password
              </label>
              <input
                type="password"
                value={confirmPassword}
                onChange={e => setConfirm(e.target.value)}
                placeholder="••••••••"
                autoComplete="new-password"
                style={{
                  ...inputStyle,
                  borderColor: confirmPassword && confirmPassword !== password
                    ? COLORS.danger
                    : COLORS.border,
                }}
                onFocus={e => e.target.style.borderColor = COLORS.borderMint}
                onBlur={e  => e.target.style.borderColor =
                  confirmPassword && confirmPassword !== password
                    ? COLORS.danger : COLORS.border}
              />
              {confirmPassword && confirmPassword !== password && (
                <div style={{
                  fontSize:   '11px',
                  fontFamily: 'var(--font-mono)',
                  color:      COLORS.danger,
                  marginTop:  '5px',
                }}>
                  Passwords don't match
                </div>
              )}
            </div>
          )}

          {/* Submit */}
          <button
            type="submit"
            disabled={!canSubmit}
            style={{
              marginTop:    '8px',
              padding:      '12px',
              background:   !canSubmit ? COLORS.bg4 : COLORS.mint,
              border:       'none',
              borderRadius: RADIUS.md,
              fontFamily:   'var(--font-display)',
              fontWeight:   '700',
              fontSize:     '13px',
              letterSpacing:'0.06em',
              textTransform:'uppercase',
              color:        !canSubmit ? COLORS.textMuted : COLORS.bg0,
              cursor:       !canSubmit ? 'default' : 'pointer',
              boxShadow:    !canSubmit ? 'none' : SHADOW.mint,
              transition:   'all 0.15s',
            }}
          >
            {loading
              ? 'Connecting…'
              : mode === 'login' ? 'Enter →' : 'Create Account →'}
          </button>
        </form>
      </div>
    </div>
  );
}
