/**

 * src/index.js

 * App root — injects CSS vars, font imports, global styles, renders App.

 */

import React from 'react';

import ReactDOM from 'react-dom/client';

import App from './App';

import { FONT_URL, CSS_VARS } from './styles/theme';

// ── Inject Google Fonts ────────────────────────────────────────────────────────

const fontLink = document.createElement('link');

fontLink.rel  = 'stylesheet';

fontLink.href = FONT_URL;

document.head.appendChild(fontLink);

// ── Inject CSS variables + global reset ────────────────────────────────────────

const style = document.createElement('style');

style.textContent = `

  ${CSS_VARS}

  *, *::before, *::after {

    box-sizing: border-box;

    margin: 0;

    padding: 0;

  }

  html, body, #root {

    height: 100%;

    overflow: hidden;

  }

  body {

    background:  var(--bg0);

    color:       var(--text-primary);

    font-family: var(--font-body);

    font-size:   14px;

    -webkit-font-smoothing: antialiased;

  }

  /* Scrollbar */

  ::-webkit-scrollbar       { width: 4px; height: 4px; }

  ::-webkit-scrollbar-track { background: transparent; }

  ::-webkit-scrollbar-thumb { background: var(--bg4); border-radius: 4px; }

  ::-webkit-scrollbar-thumb:hover { background: var(--mint-dim); }

  /* Message slide-in animation */

  @keyframes fadeSlideIn {

    from { opacity: 0; transform: translateY(6px); }

    to   { opacity: 1; transform: translateY(0); }

  }

  /* Toast slide-in */

  @keyframes toastIn {

    from { opacity: 0; transform: translateX(20px); }

    to   { opacity: 1; transform: translateX(0); }

  }

  /* Pulsing dot */

  @keyframes pulse {

    0%, 100% { opacity: 1; }

    50%       { opacity: 0.4; }

  }

  button { outline: none; }

  textarea { resize: none; }

  input::placeholder, textarea::placeholder { color: var(--text-muted); }

`;

document.head.appendChild(style);

// ── Render ─────────────────────────────────────────────────────────────────────

const root = ReactDOM.createRoot(document.getElementById('root'));

root.render(

  <React.StrictMode>

    <App />

  </React.StrictMode>

);

